ixp_model = ixp_defaults['model']
# modelName is null — use modelDisplayName per impl.md authoring rule #1
model_name = ixp_model.get('modelName') or ixp_model.get('modelDisplayName','')

# Build the flow
flow = {
  "id": "7a3b5bab-7593-4889-97c3-7c2b81758ab7",
  "version": "1.8",
  "name": "BirthCertificate",
  "nodes": [
