      "type": "core.trigger.manual",
      "typeVersion": "1.0",
      "display": {"label": "Manual trigger"},
      "inputs": {
        "entryPointId": "cd2d1738-6db9-4c7a-8cf2-d1a8a74980ab",
        "isDefaultEntryPoint": True
      }
    },
    {
      "id": "extractBirthCert",
      "type": ixp_node['nodeType'],
      "typeVersion": ixp_node.get('version',''),
      "display": {"label": "Extract Birth Certificate Fields"},
      "inputs": {
        "model": {
          "id": ixp_model.get('id',''),
          "modelName": model_name,
          "modelDisplayName": ixp_model.get('modelDisplayName',''),
          "folderKey": ixp_model.get('folderKey',''),
