        "fileRef": "=js:$vars.start.output.birthCertificate",
        "pageRange": ""
      },
      "outputs": {
        "output": ixp_node['outputDefinition']['output'],
        "error": ixp_node['outputDefinition']['error']
      }
    },
    {
      "id": "logChildName",
      "type": "core.action.script",
      "typeVersion": script_node.get('version',''),
      "display": {"label": "Log Child Full Name"},
      "inputs": {
        "script": "var fields = ($vars.extractBirthCert.output.ExtractionResult || {});\nfields = (fields.ResultsDocument || {}).Fields || [];\nvar get = function(name) {\n  var f = fields.filter(function(x) { return x.FieldName === name; })[0];\n  return f ? (f.Values || [])[0] || null : null;\n};\nvar childFullName = get('Child Full Name') || get('Full Name') || get('Child Name') || get('Child\\'s Name') || null;\nvar dateOfBirth = get('Date of Birth') || get('Birth Date') || get('Date Of Birth') || null;\nvar placeOfBirth = get('Place of Birth') || get('Birth Place') || get('Place Of Birth') || null;\nvar fatherName = get('Father Name') || get(\"Father's Name\") || get('Father\\'s Name') || null;\nvar motherName = get('Mother Name') || get(\"Mother's Name\") || get('Mother\\'s Name') || null;\nreturn {\n  childFullName: childFullName,\n  dateOfBirth: dateOfBirth,\n  placeOfBirth: placeOfBirth,\n  fatherName: fatherName,\n  motherName: motherName,\n  logMessage: 'Child Full Name: ' + childFullName\n};"
      },
